bool id_ipseckey_allowed ( struct ike_sa * ike , enum ikev2_auth_method atype ) { const struct connection * c = ike -> sa . st_connection ; struct id id = c -> remote -> host . id ; if ( c -> remote -> host . config -> auth == AUTH_RSASIG && ( id . kind == ID_FQDN || id_is_ipaddr ( & id ) ) ) { switch ( atype ) { case IKEv2_AUTH_RESERVED : case IKEv2_AUTH_DIGSIG : case IKEv2_AUTH_RSA : return true ; default : break ; } } if ( DBGP ( DBG_BASE ) ) { esb_buf eb2 ; const char * err1 = "%dnsondemand" ; const char * err2 = "" ; if ( atype != IKEv2_AUTH_RESERVED && ! ( atype == IKEv2_AUTH_RSA || atype == IKEv2_AUTH_DIGSIG ) ) { err1 = " initiator IKEv2 Auth Method mismatched " ; err2 = str_enum ( & ikev2_auth_method_names , atype , & eb2 ) ; } if ( id . kind != ID_FQDN && id . kind != ID_IPV4_ADDR && id . kind != ID_IPV6_ADDR ) { err1 = " mismatched ID type, that ID is not a FQDN, IPV4_ADDR, or IPV6_ADDR id type=" ; err2 = enum_show ( & ike_id_type_names , id . kind , & eb2 ) ; } id_buf thatid ; endpoint_buf ra ; DBG_log ( "%s #%lu not fetching ipseckey %s%s remote=%s thatid=%s" , c -> name , ike -> sa . st_serialno , err1 , err2 , str_endpoint ( & ike -> sa . st_remote_endpoint , & ra ) , str_id ( & id , & thatid ) ) ; } return false ; } 